local LadderRiseFieldNames = {
    {"redAttr%s"     , "attrId"}, --- 属性id
    {"redNum%s"      , "num"   }, --- 属性数值
    {"redLimit%s"    , "limit" }, --- 属性最大值
    {"redMin%s"      , "min"   }, --- 随机下限系数
    {"redMax%s"      , "max"   }, --- 随机上限系数
}

---@class LadderRiseAttr
---@field attrId number 属性id
---@field num number 属性数值
---@field limit number 属性最大值
---@field min number 随机下限系数
---@field max number 随机上限系数
---@field isUnlock boolean 是否解锁
---@field quality number 属性品质
---@field attrProgress number 属性进度
---@field unlockLimitId number|nil 解锁限制id

---@return LadderRiseAttr[]
function EquipDojo:GetLadderRiseAttrs()
    ---@type CardProgressionConstants
    local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
    local startStar = EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar)
    local res = {}
    if checkNumber(self.star) < startStar then
        return res
    end
    local num = EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.AttrCount)
    local qualityScopes = EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.QualityScope)
    for i = 1, num, 1 do
        local t = {}
        for key, value in pairs(LadderRiseFieldNames) do
            local fieldName, covertFieldName = SafeUnpack(value)
            local fieldV = self[string.format(fieldName, i)]
            t[covertFieldName] = checkNumber(fieldV)
        end

        local attrNum = t.num
        local maxNum  = t.limit
        local temp = attrNum / maxNum
        local maxQualityCount = #qualityScopes
        for quality = maxQualityCount - 1, 1, -1 do
            local scope = qualityScopes[quality]
            if temp >= scope then
                t.quality = quality
                break
            end
        end
        if t.quality == nil or t.quality == 0 then
            t.quality = 1
        end

        t.attrProgress = math.min(1, temp)

        if i == 2 then
            t.isUnlock, t.unlockLimitId = EquipUtils.IsUnlockLadderRiseSecondAttr(self)
        else
            t.isUnlock = true
        end

        table.insert(res, t)
    end

    return res
    
end

---@param func fun(attrId:number, attrNum:number)
function EquipDojo:WalkLadderRiseAttrs(func)
    ---@type CardProgressionConstants
    local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
    local num = EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.AttrCount)
    for i = 1, num, 1 do
        local isUnLock = true
        if i == 2 then
            isUnLock = EquipUtils.IsUnlockLadderRiseSecondAttr(self)
        end
        if isUnLock then
            func(self[string.format("redAttr%s", i)], self[string.format("redNum%s", i)])
        end
    end
end

return EquipDojo